    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]

    stripe_row = next(
        (r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != background),
        None
    )
    stripe_col = next(
        (c for c in range(w)
         if len({grid[r][c] for r in range(h)}) == 1
         and grid[0][c] != background),
        None
    )

    if stripe_row is not None:
